codeExample:
const middlewareA = store => next => action => {
  console.log('A: Entering');
  next(action); // Passes to B
  console.log('A: Exiting');
};

const middlewareB = store => next => action => {
  console.log('B: Entering');
  next(action); // Passes to Reducer!
  console.log('B: Exiting');
};

/* 
  If an action is dispatched, the console output is:
  A: Entering
  B: Entering
  --- (Reducer updates state) ---
  B: Exiting
  A: Exiting
*/
